import js from "@eslint/js"
import { defineConfigWithVueTs, vueTsConfigs } from "@vue/eslint-config-typescript"
import pluginVue from "eslint-plugin-vue"
import vueI18n from "@intlify/eslint-plugin-vue-i18n"

export default defineConfigWithVueTs(
  // src/client is generated by openapi-ts and is not edited by hand. Test
  // reports are generated bundles and traces, not sources.
  {
    ignores: [
      "dist/**",
      "src/client/**",
      "node_modules/**",
      "blob-report/**",
      "playwright-report/**",
      "test-results/**",
    ],
  },
  js.configs.recommended,
  pluginVue.configs["flat/recommended"],
  vueTsConfigs.recommended,
  {
    rules: {
      "vue/multi-word-component-names": "off",
    },
  },
  {
    // Server state belongs in vue-query, not in Pinia. Server data copied into
    // stores, each with its own cache and invalidation, falls out of step with
    // the server. A store that talks to the API is the first step towards that.
    files: ["src/stores/**"],
    rules: {
      "no-restricted-imports": [
        "error",
        {
          patterns: [
            {
              group: ["@/client", "@/client/*", "@/features/*"],
              message:
                "Stores hold client state only. Server state goes through vue-query in a feature's api.ts.",
            },
          ],
        },
      ],
    },
  },
  {
    // The shared kit owns everything with a choice of appearance, so a screen
    // asks for meaning ("danger") rather than for a look ("flat color=negative").
    // Only components the kit replaces are listed: forbidding every q-* would
    // make the kit a full facade over Quasar, which it deliberately is not.
    // Reasoning: docs/decisions/2026-08-22-shared-ui-kit-design.md
    files: ["src/**/*.vue", "src/**/*.ts"],
    ignores: ["src/shared/ui/**", "src/client/**"],
    rules: {
      "vue/no-restricted-html-elements": [
        "error",
        ...[
          ["q-dialog", "AppDialog"],
          ["q-card", "AppCard or AppDialog"],
          ["q-card-section", "AppSection"],
          ["q-card-actions", "AppActions"],
          ["q-btn", "AppButton or AppIconButton"],
          ["q-tooltip", "AppTooltip"],
          ["q-banner", "AppBanner"],
          ["q-input", "AppInput"],
          ["q-select", "AppSelect"],
          ["q-toggle", "AppToggle"],
          ["q-checkbox", "AppCheckbox"],
          ["q-radio", "AppRadioGroup"],
          ["q-option-group", "AppRadioGroup or AppCheckbox"],
          ["q-color", "AppColorPicker"],
          ["q-file", "AppFileInput"],
          ["q-table", "AppTable"],
          ["q-badge", "AppBadge"],
          ["q-spinner", "AppSpinner"],
          ["q-tree", "AppTree"],
          ["q-menu", "AppMenu"],
          // No replacement of their own: they are how AppMenu is built, and a
          // list of items is not a thing a screen should assemble by hand.
          ["q-list", "AppMenu"],
          ["q-item", "AppMenu"],
        ].map(([element, replacement]) => ({
          // The rule matches the raw tag name, so both spellings Vue accepts
          // are listed. With only the kebab one, <QBtn> walks past the list.
          element: [element, element.replace(/(^|-)(\w)/g, (_, __, c) => c.toUpperCase())],
          message: `Use ${replacement} from @/shared/ui instead of <${element}>.`,
        })),
      ],
      "no-restricted-imports": [
        "error",
        {
          paths: [
            {
              name: "quasar",
              importNames: ["useQuasar"],
              message:
                "Notifications go through useToast and confirmations through useConfirm, both in @/shared/ui.",
            },
            {
              name: "vue-i18n",
              importNames: ["useI18n"],
              message:
                "Words come from t in @/shared/i18n: it takes only keys the dictionaries have, vue-i18n's takes any string (D224).",
            },
          ],
        },
      ],
    },
  },
  {
    // Both exist only in a secure context, so over plain HTTP to another
    // machine they are undefined and whatever calls them stops working.
    files: ["src/**/*.vue", "src/**/*.ts"],
    ignores: ["src/shared/ids.ts", "src/shared/clipboard.ts", "src/**/*.spec.ts"],
    rules: {
      "no-restricted-properties": [
        "error",
        { object: "crypto", property: "randomUUID", message: "Use newId from @/shared/ids." },
        {
          object: "navigator",
          property: "clipboard",
          message: "Use copyText or readText from @/shared/clipboard.",
        },
      ],
    },
  },
  {
    // A screen speaks through the dictionaries (D224): text written into a
    // template, or into an attribute a person reads, is English in every
    // language. Words in .ts modules are not seen here and rest on review.
    files: ["src/**/*.vue"],
    // Pages a development server alone routes to; no build ships them.
    ignores: ["src/features/dev/**"],
    plugins: { "@intlify/vue-i18n": vueI18n },
    rules: {
      "@intlify/vue-i18n/no-raw-text": [
        "error",
        {
          attributes: {
            "/.*/": [
              "label",
              "title",
              "summary",
              "caption",
              "placeholder",
              "hint",
              "tooltip",
              "message",
              "aria-label",
              "confirm-label",
              "cancel-label",
              "description",
            ],
          },
          // Punctuation and marks are not words.
          ignorePattern: String.raw`^[\s\p{P}\p{S}0-9]+$`,
        },
      ],
    },
  }
)
